<template>
 <section class="factor-library" aria-label="因子库">
  <div class="factor-heading"><div><h3>因子库</h3><p>先固定公式，再在项目的数据上检验。</p></div><el-button :disabled="!canEdit" @click="newFactor">登记因子</el-button></div>
  <div class="factor-cards"><button v-for="item in factors" :key="item.id" :class="{selected:item.id===selectedId}" @click="selectedId=item.id"><strong>{{item.name}} · v{{item.version}}</strong><small>{{item.formula}}</small><span>窗口 {{item.lookback}} 根 · {{item.availability}}</span></button></div>
  <p v-if="!factors.length" class="factor-note">从历史收益、波动或均价偏离开始。只执行内置公式。</p>
  <template v-if="selected"><el-button text :disabled="!canEdit" @click="editFactor">修改定义并保存新版本</el-button><h3>{{selected.name}} · v{{selected.version}}</h3><p>{{selected.description}}</p><pre>{{selected.formula}}</pre><p class="factor-note">输入：{{selected.inputs.join('、')}}。{{selected.availability}}。</p>
   <el-form label-position="top" class="factor-form" :disabled="!canEdit"><el-form-item label="研究项目"><el-select v-model="form.project_id" aria-label="因子研究项目"><el-option v-for="item in projects" :key="item.id" :value="item.id" :label="item.title"/></el-select></el-form-item><el-form-item label="WT闭合历史"><el-select v-model="form.dataset" aria-label="因子历史数据" @change="selectDataset"><el-option v-for="item in datasets" :key="item.id" :value="item.id" :label="item.label"/></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.start" type="date" value-format="YYYYMMDD" aria-label="因子开始日期"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.end" type="date" value-format="YYYYMMDD" aria-label="因子结束日期"/></el-form-item><el-form-item label="评价持有期（根）"><el-input-number v-model="form.horizon" :min="1" :max="100"/></el-form-item><el-form-item label="关联WT回测（可选）"><el-select v-model="form.native_experiment_id" clearable><el-option v-for="item in linkedExperiments" :key="item.id" :value="item.id" :label="item.code+' · '+item.status+' · '+item.id.slice(0,8)"/></el-select></el-form-item></el-form>
   <el-button type="primary" :disabled="!canEdit||!form.project_id||!form.dataset" :loading="running" @click="run">运行因子诊断</el-button><p class="factor-note">因子用到当前闭合K线。评价从下一根收盘开始。费用、成交和资金收益仍由WT回测计算。</p>
  </template>
  <h3>因子实验</h3><el-table :data="visibleExperiments" empty-text="登记因子后，选择项目和数据运行实验"><el-table-column label="因子 / 版本" min-width="150"><template #default="{row}">{{row.factor_snapshot?.name}} · v{{row.factor_version}}</template></el-table-column><el-table-column prop="project_title" label="项目" min-width="160"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="有效样本" width="100"><template #default="{row}">{{row.diagnostics?.paired_rows??'—'}}</template></el-table-column><el-table-column label="IC" width="100"><template #default="{row}">{{number(row.diagnostics?.ic)}}</template></el-table-column><el-table-column label="RankIC" width="100"><template #default="{row}">{{number(row.diagnostics?.rank_ic)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text @click="read(row)">查看诊断</el-button></template></el-table-column></el-table>
  <el-dialog v-model="editing" title="登记因子" width="min(600px,94vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="draft.name" aria-label="因子名称"/></el-form-item><el-form-item label="内置公式"><el-select v-model="draft.builtin_id" aria-label="内置因子公式"><el-option v-for="item in builtins" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><p>{{builtin?.description}}</p><pre>{{builtin?.formula}}</pre><el-form-item label="回看窗口（根）"><el-input-number v-model="draft.lookback" :min="2" :max="500"/></el-form-item><el-form-item label="关联研报"><el-select v-model="draft.report_id" clearable><el-option v-for="item in reports" :key="item.id" :value="item.id" :label="item.title"/></el-select></el-form-item><el-form-item label="经济含义与实验预期"><el-input v-model="draft.description" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存定义</el-button></template></el-dialog>
  <el-drawer v-model="reading" title="因子诊断" size="min(850px,96vw)"><template v-if="detail"><p>{{detail.factor_experiment.reproduction_level}}</p><el-alert v-if="detail.factor_experiment.error" :title="detail.factor_experiment.error" type="error" :closable="false"/><template v-if="detail.analysis"><p>{{detail.analysis.diagnostics.timing}}</p><p>有效配对 {{detail.analysis.diagnostics.paired_rows}} 条；预热跳过 {{detail.analysis.diagnostics.warmup_skips}} 条；末尾未配对 {{detail.analysis.diagnostics.unlabelled_rows}} 条。</p><p>IC：{{number(detail.analysis.diagnostics.ic)}} · RankIC（排序相关）：{{number(detail.analysis.diagnostics.rank_ic)}}</p><p>单合约按时间诊断，不是多资产截面排名。</p><el-table v-if="detail.analysis.diagnostics.time_stability" :data="detail.analysis.diagnostics.time_stability"><el-table-column prop="segment" label="时间分段"/><el-table-column prop="paired_rows" label="有效样本"/><el-table-column label="RankIC"><template #default="{row}">{{number(row.rank_ic)}}</template></el-table-column></el-table><FactorCharts :key="detail.factor_experiment.id" :id="detail.factor_experiment.id"/><p>{{detail.analysis.diagnostics.interpretation}}</p><el-table :data="detail.analysis.diagnostics.groups"><el-table-column prop="group" label="因子从低到高分组"/><el-table-column prop="count" label="样本数"/><el-table-column label="后续收益均值"><template #default="{row}">{{number(row.mean_forward_return)}}</template></el-table-column></el-table><a :href="detail.factor_experiment.download_url" target="_blank" rel="noopener">下载全部逐点因子CSV</a><a :href="detail.factor_experiment.input_download_url" target="_blank" rel="noopener">下载固定的输入收盘价CSV</a><details><summary>输入与公式版本</summary><pre>{{JSON.stringify({factor:detail.analysis.factor_snapshot,data:detail.analysis.input_snapshot},null,2)}}</pre></details><el-table :data="detail.analysis.samples" max-height="360"><el-table-column prop="available_at" label="可用时刻" min-width="160"/><el-table-column prop="value" label="因子值" min-width="160"/><el-table-column prop="evaluation_entry" label="评价起点" min-width="160"/><el-table-column prop="forward_return" label="后续收益" min-width="160"/></el-table></template></template></el-drawer>
 </section>
</template>
<script>
import FactorCharts from './FactorCharts.vue'
export default {
 components:{FactorCharts},
 name:'ResearchFactorLibrary',props:{factors:{type:Array,default:()=>[]},builtins:{type:Array,default:()=>[]},experiments:{type:Array,default:()=>[]},nativeExperiments:{type:Array,default:()=>[]},projects:{type:Array,default:()=>[]},datasets:{type:Array,default:()=>[]},reports:{type:Array,default:()=>[]},project:Object,canEdit:Boolean},emits:['refresh'],
 data:()=>({selectedId:'',editing:false,saving:false,running:false,reading:false,detail:null,draft:{name:'',builtin_id:'momentum',lookback:20,report_id:'',description:''},form:{project_id:'',dataset:'',start:'',end:'',horizon:1,native_experiment_id:''}}),
 computed:{selected(){return this.factors.find(x=>x.id===this.selectedId)},builtin(){return this.builtins.find(x=>x.id===this.draft.builtin_id)},visibleExperiments(){return this.project?this.experiments.filter(x=>x.project_id===this.project.id):this.experiments},linkedExperiments(){return this.nativeExperiments.filter(x=>x.project_id===this.form.project_id)}},
 watch:{project:{immediate:true,handler(value){if(value)this.form.project_id=value.id}},factors:{immediate:true,handler(value){if(!this.selectedId&&value.length)this.selectedId=value[0].id}}},
 methods:{newFactor(){this.draft={name:'',builtin_id:'momentum',lookback:20,report_id:this.project?.report_id||'',description:''};this.editing=true},editFactor(){this.draft={...this.selected};this.editing=true},number(value){return value==null?'—':Number(value).toPrecision(6)},async request(action,body){const response=await fetch('/mgr/research/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok||result.result<0)throw new Error(result.message||'因子请求失败');return result},selectDataset(){const row=this.datasets.find(x=>x.id===this.form.dataset);if(row){this.form.start=String(row.start).slice(0,8);this.form.end=String(row.end).slice(0,8)}},async save(){this.saving=true;try{const result=await this.request('factor_save',this.draft);this.selectedId=result.factor.id;this.editing=false;this.$emit('refresh');this.$message.success('因子定义已保存')}catch(error){this.$message.error(error.message)}finally{this.saving=false}},async run(){this.running=true;try{await this.request('factor_run',{...this.form,factor_id:this.selectedId,start:Number(this.form.start),end:Number(this.form.end)});this.$emit('refresh');this.$message.success('因子实验已启动')}catch(error){this.$message.error(error.message)}finally{this.running=false}},async read(row){try{this.detail=await this.request('factor_detail',{experiment_id:row.id});this.reading=true}catch(error){this.$message.error(error.message)}}}
}
</script>
<style scoped>
.factor-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.factor-heading p,.factor-note{color:var(--wt-muted);font-size:12px;line-height:1.8}.factor-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:18px 0}.factor-cards button{display:flex;flex-direction:column;gap:9px;text-align:left;border:1px solid var(--wt-line);background:var(--wt-surface);color:var(--wt-text);padding:16px;border-radius:6px;cursor:pointer}.factor-cards button.selected{background:var(--wt-matte);border-color:var(--wt-text)}.factor-cards small,.factor-cards span{color:var(--wt-muted);overflow-wrap:anywhere}.factor-form{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.factor-form .el-select,.factor-form .el-date-editor{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:var(--wt-matte);padding:14px;line-height:1.8}h3{font-size:15px;font-weight:550;margin:20px 0 12px}a{display:block;margin:18px 0;color:var(--wt-text)}@media(max-width:650px){.factor-form{grid-template-columns:1fr}.factor-heading{align-items:flex-start}}
</style>
